// URL slug: lowercase, runs of non-alphanumerics become a single dash,
// with leading and trailing dashes stripped.
export function slugify(s) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

